-- Saca de las búsquedas de chess-results en todos los países (ver «Árbitros
-- de Costa Rica en el extranjero» en docs/decisiones/juegos-y-torneos.md)
-- las filas que sirven: un torneo de otra federación cuyas casillas de
-- árbitro principal, adjunto o árbitros nombran a alguien de la lista, por su
-- ID FIDE o por su primer apellido y su primer nombre como palabras sueltas.
-- Sin una expresión regular por árbitro (con 166 distintas la consulta pasaba
-- del minuto con una sola página de 1,5 MB) y con celdas y t materializadas:
-- si no, Postgres las metía dentro del join y las recalculaba por cada par
-- fila × árbitro.
-- Es un colador grueso (el reconocimiento fino lo hace
-- herramientas/arbitros-cr.py); la lista `a` sale de arbitros_cr. Se corre
-- por tramos de respuestas (:d a :h, ids de net._http_response): todo junto
-- pasa del minuto. Cada respuesta va a herramientas/arbitros-cr/juntar-afuera.py.
set statement_timeout = '55s';
with a(fid, ap, no) as (values ('6501400','araya','luis'),('6501397','redondo','diego'),('6504035','bermudez','pablo'),('6500439','cordoba','edwin'),('6500170','gonzalez','bernal'),('6502199','corella','luis'),('6502857','murillo','gustavo'),('6501745','alvarado','sara'),('6505244','castro','mauricio'),('6500420','alvarado','dizan'),('6503950','alvarado','sergio'),('6502270','gamboa','olga'),('6503306','zumbado','marco'),('6500650','urbina','edwin'),('6500218','murillo','alexis'),('6502822','amaya','alvaro'),('6506780','alvarado','shirley'),('6500579','munoz','carolina'),('6500358','barrios','carlos'),('6501168','jimenez','fabian'),('6508162','bustos','fiorella'),('6501435','angulo','oscar'),('6501621','fernandez','mario'),('6505473','morera','yanori'),('6508693','chinchilla','alejandra'),('6500404','gonzalez','paul'),('6508804','jimenez','rebeca'),('6504191','alvarado','jeaustin'),('6500986','fallas','betzy'),('6501176','jimenez','gustavo'),('6505694','nunez','joshebeth'),('6508650','herrera','maria'),('6505007','ramirez','joan'),('6502229','elizondo','grettel'),('6502946','araya','cristian'),('6500056','alvarez','david'),('6501923','aguilar','alberto'),('6503489','cordero','nelson'),('6509479','mesen','elias'),('6503594','quiros','allan'),('6504396','nunez','neeshmy'),('6509797','rivera','isaac'),('6509959','miranda','keylor'),('6502903','rodriguez','jose'),('6508677','rivera','juan'),('6502849','gomez','stanley'),('6500625','carvajal','jonathan'),('6509576','salazar','carlos'),('6506216','bonilla','kevin'),('6501460','badilla','johans'),('6504892','murillo','carlos'),('6500226','hernandez','francisco'),('6510590','murillo','ricardo'),('6517099','amaya','greyvin'),('6505716','salas','pamela'),('6518877','diaz','gerardo'),('6526683','sanchez','pablo'),('6506178','castro','juan'),('6500676','vargas','pablo'),('6501451','artavia','jose'),('6508189','arguello','graciela'),('6526900','araya','jose'),('6506089','bonilla','luis'),('6506097','chaves','jose'),('6511201','g