r as (select id, substr(content, strpos(content, '<table class="CRs2"')) t from net._http_response where id between :d and :h and id <> 18349 and strpos(content, '<table class="CRs2"') > 0),
filas as (select f from r, regexp_split_to_table(substr(t, 1, strpos(t, '</table>')), '<tr class="CR') f where f ~ '^n?g[12]">'),
celdas as materialized (select regexp_split_to_array(f, '</t[dh]>') c from filas),
t as materialized (select btrim(regexp_replace(c[19], '<[^>]+>', '', 'g')) k, c, ' ' || regexp_replace(translate(lower(regexp_replace(c[10] || ' | ' || c[11] || ' | ' || c[12], '<[^>]+>', ' ', 'g')), 'áéíóúüñàèìòùâêîôûÁÉÍÓÚÑ', 'aeiouunaeiouaeiouaeioun'), '[^a-z0-9]+', ' ', 'g') || ' ' x
  from celdas where btrim(regexp_replace(c[3], '<[^>]+>', '', 'g')) <> 'CRC'),
s as (select distinct on (t.k) t.k, t.c from t join a on strpos(t.x, ' ' || a.fid || ' ') > 0 or (strpos(t.x, ' ' || a.ap || ' ') > 0 and strpos(t.x, ' ' || a.no || ' ') > 0) where t.k ~ '^\d+$')
select count(*) n, json_agg(json_build_array(k, (select array_agg(btrim(regexp_replace(regexp_replace(x, '<[^>]+>', '', 'g'), '\s+', ' ', 'g')) order by o) from unnest(c[2:18]) with ordinality u(x, o)))) filas from s;